changeSet.neo4j:cypher:
CREATE INDEX term_origin_name_idx IF NOT EXISTS
FOR (t:term)
ON (t.origin_name);

CREATE INDEX term_cde_lookup_idx IF NOT EXISTS
FOR (t:term)
ON (t.origin_name, t.origin_id, t.handle, t.origin_version);

CREATE INDEX term_crdc_lookup_idx IF NOT EXISTS
FOR (t:term)
ON (t.origin_name, t.origin_id);

CREATE INDEX vs_nanoid_idx IF NOT EXISTS
FOR (vs:value_set)
ON (vs.nanoid);

CREATE INDEX vs_handle_idx IF NOT EXISTS
FOR (vs:value_set)
ON (vs.handle);

CALL {
// ---------- CREATE VALUESET and ATTACH UBERON TEMS ---------- MERGE (vs:value_set {nanoid: "6ucHaW"}) ON CREATE SET vs._commit = "test-Uberon-20260317", vs.handle = "uberon_terms_valueset"
WITH vs
MATCH (t:term {origin_name:"UBERON"}) MERGE (vs)-[:has_term]->(t)
WITH vs
// ---------- CREATE CRDC TERM ---------- MERGE (ref:term { origin_name: "CRDC", origin_id: "CRDC0001" }) ON CREATE SET ref._commit = "CDEPV-20260420" ON CREATE SET ref.nanoid = "Vsv9y2" ON CREATE SET ref.origin_version = "1" ON CREATE SET ref.value = "uberon value set reference" ON CREATE SET ref.handle = "uberon_valueset_reference"
WITH vs, ref
// ---------- CREATE TAGS ---------- MERGE (tag1:tag {key: "provenance", value: "CTOS experts"}) ON CREATE SET tag1._commit = "test-Uberon-20260317"
MERGE (tag2:tag {key: "added", value: "04-21-2026"}) ON CREATE SET tag2._commit = "test-Uberon-20260317"
MERGE (ref)-[:has_tag]->(tag1) MERGE (ref)-[:has_tag]->(tag2)
WITH vs, ref
// ---------- LINK CRDC TERM TO VALUESET ---------- MERGE (ref)-[:specifies_value_set]->(vs)
WITH vs
// ---------- CDE MAPPINGS ---------- UNWIND [ { cde_handle: "disease_primary_site_of_disease_uberon_identifier", origin_id: "14883047"), { cde_handle: "disease_tissue_or_organ_of_origin_anatomic_site_uberon_identifier", origin_id: "14883058"}, { cde_handle: "disease_site_of_resection_or_biopsy_uberon_identifier", origin_id: "14883054"}, { cde_handle: "specimen_original_anatomic_site_uberon_identifier", origin_id: "12083894"}, { cde_handle: "specimen_original_anatomic_site_uberon_name", origin_id: "12299653"} ] AS row
MATCH (cde:term { handle: row.cde_handle, origin_id: row.origin_id, origin_name: "caDSR", origin_version: "1.00" })
WITH cde, vs MERGE (cde)-[:specifies_value_set]->(vs)
}
